template <typename T>
class ResourceHolder {
    T object_;
public:
    // Template constructor using forwarding reference (U&&)
    template <typename U>
    ResourceHolder(U&& arg)
        // Perfect forwarding
        : object_(std::forward<U>(arg))
    {
        // U&& must deduce the type (T, T&, or T const&)
    }
};
